<script setup lang="ts">
import { computed,onUnmounted,reactive,ref,watch } from 'vue'
import { all,ApiError,api,dateTimeLabel,durationLabel,isProjectReadOnly,localDate,messageOf,notify,projectName,query,ui } from '../api'
import { membersChanged } from '../projectMembers'
import type { LanDailyEntry,LanMember,LanStatus } from '../lan'
import type { Page,Task } from '../types'
import Modal from './Modal.vue'
import Pager from './Pager.vue'
import ConflictNotice from './ConflictNotice.vue'
import { useConflict } from '../drafts'
const opened=ref(false),status=ref<LanStatus>(),members=ref<LanMember[]>([]),port=ref(18680),loading=ref(false),controlling=ref(false),saving=ref(false),error=ref(''),editor=ref(false),editing=ref<LanMember>(),tasks=ref<Task[]>([]),taskLoading=ref(false),taskError=ref(''),taskSearch=ref(''),operation=ref(''),pairing=ref<{code:string;expires_at:string;member:LanMember}>(),pairOpen=ref(false),pairCopied=ref(false),pairMessage=ref(''),pairError=ref('')
const form=reactive({name:'',enabled:true,project_ids:[] as string[],task_ids:[] as string[]}),baseline=ref(''),conflict=useConflict(),daily=ref<LanDailyEntry[]>([]),dailyTotal=ref(0),dailyOffset=ref(0),dailyLoading=ref(false),dailyError=ref(''),dailyFilters=reactive({project_id:'',work_date:localDate(),member_id:''}),limit=15
const journalPreview=ref<{content:string;source_snapshot?:{people?:Array<{person_name:string;minutes:number;submitted:boolean}>;lan_people?:Array<{member_id:string;person_name:string;minutes:number;submitted:boolean}>;missing_people?:string[];total_minutes?:number}}>(),previewLoading=ref(false),previewError=ref('')
let treeRequest=0,dailyRequest=0,previewRequest=0,refreshTimer:ReturnType<typeof setInterval>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined,copyTimer:ReturnType<typeof setTimeout>|undefined
const dirty=computed(()=>editor.value&&JSON.stringify(form)!==baseline.value),writableProjects=computed(()=>ui.projects.filter(p=>!isProjectReadOnly(p.id)||form.project_ids.includes(p.id))),taskOptions=computed(()=>tasks.value.filter(t=>form.project_ids.includes(t.project_id)&&!t.has_children&&(!['done','canceled'].includes(t.status)||!!editing.value?.task_ids.includes(t.id))&&(!taskSearch.value.trim()||`${t.wbs_code} ${t.name} ${t.assignee}`.toLowerCase().includes(taskSearch.value.trim().toLowerCase())))),unavailableTasks=computed(()=>form.task_ids.filter(id=>!tasks.value.some(t=>t.id===id&&!t.has_children)))
function canLeave(){if(saving.value||controlling.value||operation.value)return false;return !dirty.value||window.confirm('成员授权修改尚未保存，确定离开？')}
function assign(member?:LanMember){editing.value=member;Object.assign(form,{name:member?.name||'',enabled:member?.enabled??true,project_ids:[...(member?.project_ids||[])],task_ids:[...(member?.task_ids||[])]});baseline.value=JSON.stringify(form)}
async function load(){loading.value=true;error.value='';try{const [runtime,list]=await Promise.all([api<LanStatus>('/api/lan/status'),all<LanMember>('/api/lan/members')]);status.value=runtime;port.value=runtime.port||18680;members.value=list}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
function toggle(event:Event){opened.value=(event.target as HTMLDetailsElement).open;if(opened.value){if(!dailyFilters.project_id)dailyFilters.project_id=ui.projects.find(p=>!isProjectReadOnly(p.id))?.id||ui.projects[0]?.id||'';void load();void refreshReceived();refreshTimer=setInterval(()=>void refreshReceived(),30000)}else clearInterval(refreshTimer)}
async function renewCertificate(){if(controlling.value||status.value?.running||!window.confirm('重新生成证书将撤销全部成员会话。所有成员必须重新核对指纹、信任新证书并获取配对码；确定继续？'))return;controlling.value=true;error.value='';try{await api('/api/lan/certificate/renew',{method:'POST',body:'{}'});await load();notify('证书已重新生成，重新开启后请分发新证书并核对指纹')}catch(e){error.value=messageOf(e)}finally{controlling.value=false}}
async function control(enabled:boolean){if(controlling.value)return;if(!enabled&&!window.confirm('关闭局域网协同并使现有成员会话失效？本机工作台继续运行。'))return;controlling.value=true;error.value='';try{status.value=await api<LanStatus>('/api/lan/control',{method:'POST',body:JSON.stringify({enabled,port:Number(port.value)})});notify(enabled?'局域网协同已开启，请核对证书后分享成员地址':'局域网协同已关闭')}catch(e){error.value=messageOf(e);try{status.value=await api<LanStatus>('/api/lan/status')}catch{/* Keep the actionable request error. */}}finally{controlling.value=false}}
async function loadTasks(){const seq=++treeRequest;taskLoading.value=true;taskError.value='';try{const trees=await Promise.all(form.project_ids.map(id=>api<Page<Task>>(`/api/projects/${encodeURIComponent(id)}/tree`)));if(seq===treeRequest)tasks.value=trees.flatMap(page=>page.items)}catch(e){if(seq===treeRequest)taskError.value=messageOf(e)}finally{if(seq===treeRequest)taskLoading.value=false}}
async function edit(member?:LanMember){if(!canLeave())return;assign(member);taskSearch.value='';conflict.clear();editor.value=true;await loadTasks()}
function projectsChanged(){form.task_ids=form.task_ids.filter(id=>tasks.value.some(t=>t.id===id&&form.project_ids.includes(t.project_id)));void loadTasks()}
async function save(){if(saving.value||!form.name.trim()||!form.project_ids.length)return;saving.value=true;error.value='';const payload={...form,name:form.name.trim(),...(editing.value?{version:editing.value.version}:{})};try{await api<LanMember>(editing.value?`/api/lan/members/${editing.value.id}`:'/api/lan/members',{method:editing.value?'PATCH':'POST',body:JSON.stringify(editing.value?payload:{name:payload.name,project_ids:payload.project_ids,task_ids:payload.task_ids})});editor.value=false;membersChanged();notify('成员与授权已保存，姓名相同的成员仍按独立ID识别');await load()}catch(e){error.value=messageOf(e);if(editing.value&&e instanceof ApiError&&e.status===409){try{const remote=(await all<LanMember>('/api/lan/members')).find(m=>m.id===editing.value?.id);if(remote)conflict.current.value={local:JSON.parse(JSON.stringify(payload)),remote:{...remote},path:''}}catch(inner){error.value+='；'+messageOf(inner)}}}finally{saving.value=false}}
async function reloadConflict(){const member=conflict.current.value?.remote as unknown as LanMember;if(!member)return;if(dirty.value&&!window.confirm('载入服务器授权将替换此编辑区尚未保存的修改，确定载入？'))return;assign(member);conflict.clear();await loadTasks()}
async function pair(member:LanMember){if(operation.value)return;operation.value=member.id;error.value='';try{pairing.value=await api(`/api/lan/members/${member.id}/pairing`,{method:'POST',body:JSON.stringify({version:member.version})});pairCopied.value=false;pairMessage.value='';pairError.value='';pairOpen.value=true;await load()}catch(e){error.value=messageOf(e)}finally{operation.value=''}}
async function revoke(member:LanMember){if(operation.value||!window.confirm(`使「${member.name}」的已有设备会话立即失效？其已提交日志保留。`))return;operation.value=member.id;error.value='';try{await api(`/api/lan/members/${member.id}/revoke`,{method:'POST',body:JSON.stringify({version:member.version})});notify('该成员原会话已撤销，需重新配对后访问');await load()}catch(e){error.value=messageOf(e)}finally{operation.value=''}}
async function copy(value:string,inPair=false){if(inPair){pairMessage.value='';pairError.value='';pairCopied.value=false;clearTimeout(copyTimer)}try{await navigator.clipboard.writeText(value);if(inPair){pairCopied.value=true;pairMessage.value='配对码已复制，请发送给对应成员。';copyTimer=setTimeout(()=>{pairCopied.value=false},3000)}else notify('已复制')}catch{const text='浏览器不允许自动复制，请选中对应文本手动复制。';if(inPair)pairError.value=text;else error.value=text}}
async function loadDaily(){const seq=++dailyRequest;dailyLoading.value=true;dailyError.value='';try{const page=await api<Page<LanDailyEntry>>(`/api/lan/daily-entries?${query({...dailyFilters,limit,offset:dailyOffset.value})}`);if(seq===dailyRequest){daily.value=page.items;dailyTotal.value=page.total}}catch(e){if(seq===dailyRequest)dailyError.value=messageOf(e)}finally{if(seq===dailyRequest)dailyLoading.value=false}}
async function generatePreview(){const seq=++previewRequest,pid=dailyFilters.project_id,day=dailyFilters.work_date;previewError.value='';journalPreview.value=undefined;if(!pid||!day){previewLoading.value=false;return}previewLoading.value=true;try{const result=await api<{content:string;source_snapshot?:{people?:Array<{person_name:string;minutes:number;submitted:boolean}>;lan_people?:Array<{member_id:string;person_name:string;minutes:number;submitted:boolean}>;missing_people?:string[];total_minutes?:number}}>('/api/project-daily-logs/generate',{method:'POST',body:JSON.stringify({project_id:pid,log_date:day})});if(seq===previewRequest)journalPreview.value=result}catch(e){if(seq===previewRequest)previewError.value=messageOf(e)}finally{if(seq===previewRequest)previewLoading.value=false}}
async function refreshReceived(){await Promise.all([loadDaily(),generatePreview()])}
function openJournal(){if(!canLeave())return;editor.value=false;location.hash=`#/project-journal?${query({project_id:dailyFilters.project_id,log_date:dailyFilters.work_date})}`}
watch(()=>[dailyFilters.project_id,dailyFilters.work_date],()=>{clearTimeout(previewTimer);if(opened.value){dailyOffset.value=0;previewTimer=setTimeout(()=>void refreshReceived(),200)}})
onUnmounted(()=>{clearInterval(refreshTimer);clearTimeout(previewTimer);clearTimeout(copyTimer);dailyRequest++;previewRequest++;treeRequest++})
function close(){if(!saving.value&&canLeave()){editor.value=false;conflict.clear()}}
function closePair(){pairOpen.value=false;pairing.value=undefined;pairCopied.value=false;pairMessage.value='';pairError.value='';clearTimeout(copyTimer)}
defineExpose({canLeave})
</script>
<template><details class="surface lan-settings" @toggle="toggle"><summary>局域网协同 <span>负责人在本机管理，成员在受限工作台提交</span></summary><div class="lan-body"><p class="input-hint">局域网协同需显式开启。负责人权限只在本机工作台；远程成员只能查看授权项目进展、更新指定叶子任务、提交自己的每日工作与工时。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="lan-runtime"><div class="runtime-heading"><strong>{{status?.running?'局域网协同运行中':'局域网协同未运行'}}</strong><button type="button" class="text-button" :disabled="loading||controlling" @click="load">刷新</button></div><form class="lan-controls" @submit.prevent="control(true)"><label>HTTPS 端口<input v-model.number="port" required type="number" min="1024" max="65436" :disabled="controlling||status?.running"/></label><button v-if="!status?.running" class="button primary small" :disabled="controlling||loading">{{controlling?'正在开启…':'开启局域网协同'}}</button><button v-else type="button" class="button subtle small" :disabled="controlling" @click="control(false)">{{controlling?'正在关闭…':'关闭局域网协同'}}</button></form><p class="input-hint">更换网络后若证书未覆盖新地址，可先关闭协同，再明确重新生成证书。</p><button type="button" class="text-button" :disabled="controlling||status?.running" @click="renewCertificate">重新生成证书</button><p v-if="status?.error" class="form-error" role="alert">{{status.error}}</p><template v-if="status?.running"><h3>成员访问地址</h3><div v-for="address in status.addresses" :key="address" class="lan-copy-row"><code>{{address}}</code><button type="button" class="text-button" @click="copy(address)">复制地址</button></div><p class="lan-security-note">成员电脑需与本机处于可互通的局域网。先下载并在成员设备安装信任证书，用其他可信方式核对下方 SHA-256 指纹，再打开 HTTPS 地址配对。此处不代装证书、不跳过浏览器证书校验，也不修改系统防火墙。</p><div class="lan-certificate"><a class="button subtle small" :href="status.certificate_download" download>下载成员信任证书</a><span>有效期至 {{dateTimeLabel(status.certificate_expires_at)}}</span><code>{{status.certificate_sha256}}</code><button type="button" class="text-button" @click="copy(status.certificate_sha256)">复制证书指纹</button></div></template></div>
<div class="section-heading lan-section-heading"><div><h2>成员与授权 <span class="count">{{members.length}}</span></h2><p class="input-hint">按成员ID授权；项目成员名单与任务负责人共用成员ID；姓名相同的人员分别管理。</p></div><button type="button" class="button subtle small" :disabled="saving||loading" @click="edit()">新增成员</button></div><div v-if="members.length" class="table-scroll"><table class="member-list"><thead><tr><th>成员 / ID</th><th>项目与任务范围</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="member in members" :key="member.id"><td><strong>{{member.name}}</strong><small>{{member.id}}</small></td><td><span>{{member.project_ids.map(projectName).join('、')||'未授权项目'}}</span><small>指定 {{member.task_ids.length}} 项任务可更新</small></td><td>{{member.enabled?'启用':'已停用'}}</td><td class="right"><div class="row-actions"><button type="button" class="text-button" :disabled="!!operation" @click="edit(member)">编辑授权</button><button type="button" class="text-button" :disabled="!!operation||!member.enabled||!status?.running" @click="pair(member)">生成一次配对码</button><button type="button" class="text-button" :disabled="!!operation" @click="revoke(member)">撤销会话</button></div></td></tr></tbody></table></div><p v-else class="empty-state compact">还没有成员。先建立成员并明确选择项目和可更新任务。</p>
<details class="lan-daily"><summary>成员每日提交（负责人只读）</summary><form class="filter-bar" @submit.prevent="dailyOffset=0;refreshReceived()"><select v-model="dailyFilters.project_id" aria-label="成员日志项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model="dailyFilters.work_date" type="date" aria-label="成员日志日期"/><select v-model="dailyFilters.member_id" aria-label="成员日志人员"><option value="">全部成员</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}} · {{m.id.slice(0,8)}}</option></select><button class="button subtle small" :disabled="dailyLoading">查看</button></form><p class="input-hint">成员提交会进入项目日志的汇总来源；已保存日志保持原快照，需显式重新生成并核对后保存。</p><p v-if="dailyError" class="form-error" role="alert">{{dailyError}}</p><p v-if="dailyLoading" class="input-hint">正在读取成员提交…</p><div v-else-if="daily.length" class="lan-daily-list"><article v-for="entry in daily" :key="entry.id"><h3>{{members.find(m=>m.id===entry.member_id)?.name||entry.member_name||entry.member_id}} · {{entry.work_date}} <span>{{durationLabel(entry.minutes)}}</span></h3><small>{{projectName(entry.project_id)}} · 成员 {{entry.member_id}} · 版本 {{entry.version}}</small><p>{{entry.content||'未填写完成工作'}}</p><p v-if="entry.next_plan">后续计划：{{entry.next_plan}}</p><p v-if="entry.blockers" class="overdue">需协调：{{entry.blockers}}</p></article></div><p v-else class="empty-state compact">此范围暂无成员提交。</p><Pager :offset="dailyOffset" :limit="limit" :total="dailyTotal" @change="dailyOffset=$event;loadDaily()"/><section class="lan-journal-preview"><div class="section-heading"><div><h3>项目日志预览</h3><p class="input-hint">按所选项目与日期自动汇总，每 30 秒刷新收到的记录与此预览；不会覆盖或自动保存已编辑日志。</p></div><button type="button" class="text-button" :disabled="previewLoading" @click="generatePreview">刷新预览</button></div><p v-if="previewError" class="form-error" role="alert">{{previewError}}</p><p v-if="previewLoading" class="input-hint">正在汇总当前来源…</p><template v-else-if="journalPreview"><p v-if="journalPreview.source_snapshot?.missing_people?.length" class="input-hint overdue">尚未填写：{{journalPreview.source_snapshot.missing_people.join('、')}}</p><ul v-if="journalPreview.source_snapshot?.people?.length"><li v-for="person in journalPreview.source_snapshot.people" :key="person.person_name">{{person.person_name}} · {{durationLabel(person.minutes)}} · {{person.submitted?'已填写':'尚未填写'}}</li></ul><ul v-if="journalPreview.source_snapshot?.lan_people?.length"><li v-for="person in journalPreview.source_snapshot.lan_people" :key="person.member_id">{{person.person_name}}（{{person.member_id.slice(0,8)}}） · {{durationLabel(person.minutes)}} · {{person.submitted?'已提交':'当天未提交'}}</li></ul><pre tabindex="0">{{journalPreview.content}}</pre><button type="button" class="button subtle small" @click="openJournal">去项目日志整理 / 保存</button></template><p v-else-if="!dailyFilters.project_id" class="input-hint">选择一个项目后自动预览汇总。</p></section></details></div></details>
<Modal :open="editor" :title="editing?'编辑成员与授权':'新增成员'" wide @close="close"><form class="modal-body" @submit.prevent="save"><ConflictNotice :value="conflict.current.value" @keep="conflict.clear()" @reload="reloadConflict"/><p v-if="error" class="form-error" role="alert">{{error}}</p><fieldset :disabled="saving"><label>成员姓名 <span class="required">*</span><input v-model="form.name" required maxlength="100" autofocus placeholder="显示名称，同名成员用ID区分"/></label><label v-if="editing" class="checkbox-label"><input v-model="form.enabled" type="checkbox"/>启用成员（停用后无法继续访问）</label><h3 class="scope-heading">可查看的项目 <span class="required">*</span></h3><div class="scope-projects"><label v-for="p in writableProjects" :key="p.id" class="checkbox-label"><input v-model="form.project_ids" type="checkbox" :value="p.id" @change="projectsChanged"/>{{p.name}}<span v-if="isProjectReadOnly(p.id)" class="muted">（只读）</span></label></div><h3 class="scope-heading">可更新的叶子任务</h3><p class="input-hint">选择项目成员的叶子任务；分配会同步任务负责人。已完成、已取消的任务保留历史分配，不可重新指派。</p><p v-if="taskError" class="form-error" role="alert">{{taskError}}</p><p v-if="taskLoading" class="input-hint">正在读取项目任务…</p><template v-else><input v-model="taskSearch" aria-label="筛选成员任务授权" placeholder="按项目任务名、WBS或负责人筛选"/><div class="scope-tasks"><label v-for="task in taskOptions" :key="task.id" class="checkbox-label"><input v-model="form.task_ids" type="checkbox" :value="task.id" :disabled="['done','canceled'].includes(task.status)||isProjectReadOnly(task.project_id)"/>{{projectName(task.project_id)}} · {{task.wbs_code}} {{task.name}}<span v-if="['done','canceled'].includes(task.status)" class="muted">（历史分配，不能改派）</span></label><p v-if="!taskOptions.length" class="input-hint">选择项目后，可在这里指定成员可更新的叶子任务。</p></div></template><div v-if="unavailableTasks.length&&!taskLoading" class="scope-unavailable"><p>以下旧任务已不可用或变为父任务，请核对授权。</p><p v-for="id in unavailableTasks" :key="id">{{id}} <button type="button" class="text-button" @click="form.task_ids=form.task_ids.filter(t=>t!==id)">移除授权</button></p></div></fieldset><p v-if="editing" class="input-hint">保存成员或授权修改将使该成员已有会话失效，需要重新配对。成员ID {{editing.id}} · 数据版本 {{editing.version}}</p><div class="modal-footer"><button type="button" class="button subtle" :disabled="saving" @click="close">取消</button><button class="button primary" :disabled="saving||taskLoading||!form.name.trim()||!form.project_ids.length">{{saving?'正在保存…':'保存成员授权'}}</button></div></form></Modal>
<Modal :open="pairOpen" title="一次配对码" @close="closePair"><div v-if="pairing" class="modal-body"><p>{{pairing.member.name}} · {{pairing.member.id}}</p><p class="input-hint">此码仅可兑换一次，有效期至 {{dateTimeLabel(pairing.expires_at)}}。只分享给对应成员；兑换后使用该浏览器会话，不需要输入管理员密码。</p><code class="pair-code" tabindex="0">{{pairing.code}}</code><button type="button" class="button primary small" @click="copy(pairing.code,true)">{{pairCopied?'已复制':'复制配对码'}}</button><p v-if="pairMessage" class="pair-feedback" role="status">{{pairMessage}}</p><p v-if="pairError" class="form-error" role="alert">{{pairError}}</p><div class="modal-footer"><button type="button" class="button subtle" @click="closePair">关闭</button></div></div></Modal>
</template>
